insert into public.units (id, section_id, ordinal, course_order, slug, title_en, summary_en, grammar_focus, register_max, review_form_ids, status) values
  ('bf7b8307-3d3a-57b2-9e3b-06bca38b4ef1', 3, 3, 50, 'tengo-una-reserva', 'Check in at a hotel or hostel', 'Tengo una reserva', array['tener.pres.1sg', 'hay', 'a-nombre-de']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('4db2a92e-ad85-5b0f-88e2-71629dbf00d2', 3, 11, 58, 'tomar-el-bondi', 'Take the bondi and the subte', 'Cargo la SUBE y me bajo en la próxima', array['ir-a.lugar', 'bajarse.pres.1sg', 'faltar.pres.3']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('d9917aa3-1a7b-5287-9437-9c652db27797', 3, 12, 59, 'en-taxi', 'Take a taxi, remis or app car', '¿Me llevás al aeropuerto?', array['enclitico.me-te', 'ir-a.lugar']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('72bb9993-19e7-5dad-bdc7-78b4161e7045', 3, 13, 60, 'ayuda', 'Get help in an emergency', '¡Ayuda! Llamá a la policía', array['imperativo.vos.afirmativo', 'frases.emergencia']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('c15b7bfe-bc72-5bf8-a990-5ba1799a2d79', 3, 17, 64, 'debito-o-credito', 'Pay the way locals do', '¿Débito o crédito? ¿Te transfiero?', array['pagar.con', 'enclitico.me-te', 'numeros.miles']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('fa7ef0ed-4de1-5b37-9c23-1d5747ae531d', 3, 23, 70, 'pasame-tu-numero', 'Swap numbers and WhatsApp', '¿Me pasás tu número? Te escribo', array['enclitico.me-te', 'imperativo.vos.afirmativo']::text[], 'informal', '{}'::uuid[], 'draft'),
  ('4aaf79fa-f71f-5712-8a98-5facae7b4221', 12, 24, 282, 'puteadas', 'Understand the swearing', '¡Qué cagada, la puta madre!', array['registro', 'puteadas']::text[], 'vulgar', '{}'::uuid[], 'draft')
